import{rt as e,t,tt as n,xt as r}from"./chunks/framework.CRPOboOd.js";var i=JSON.parse(`{"title":"Messaging","description":"","frontmatter":{"title":"Messaging","order":2},"headers":[],"relativePath":"architecture/messaging.md","filePath":"architecture/messaging.md"}`),a={name:`architecture/messaging.md`};function o(t,i,a,o,s,c){return r(),n(`div`,{"data-pagefind-body":!0,"data-pagefind-meta":`date:1793531709000`},[...i[0]||=[e(`<h1 id="messaging" tabindex="-1">Messaging <a class="header-anchor" href="#messaging" aria-label="Permalink to “Messaging”">​</a></h1><p>Services communicate asynchronously through Redpanda (Kafka API).</p><h2 id="transactional-outbox" tabindex="-1">Transactional outbox <a class="header-anchor" href="#transactional-outbox" aria-label="Permalink to “Transactional outbox”">​</a></h2><p>Go services publish through a Watermill transactional outbox so that a domain write and the event it produces commit together. The flow in the Note service:</p><ol><li>The repository <code>Save</code> drains domain events and publishes them with the Watermill <code>forwarder</code> publisher, which writes the message into an outbox table in the same Postgres transaction as the aggregate change.</li><li>The outbox table (default name <code>eventsToForward</code>, config <code>outbox_table_name</code>) follows the Watermill SQL queue schema (deleted on ack) and is created by a goose migration.</li><li>A Watermill SQL subscriber polls the table (every second) and the forwarder re-publishes each message to its real topic on Redpanda.</li></ol><p>Because of this, publishing an integration event inside a unit of work is safe. Notifications that must not fail the request (for example billing&#39;s <code>subscription.changed</code>) are instead published best-effort after commit. NestJS services publish and consume directly with <code>@nestjs/microservices</code>.</p><h2 id="topic-naming" tabindex="-1">Topic naming <a class="header-anchor" href="#topic-naming" aria-label="Permalink to “Topic naming”">​</a></h2><table tabindex="0"><thead><tr><th>Kind</th><th>Pattern</th><th>Example</th></tr></thead><tbody><tr><td>Integration (cross-service)</td><td><code>events.integration.{service}.{aggregate}.{event}</code></td><td><code>events.integration.note.note.created</code></td></tr><tr><td>Internal (inside one service)</td><td><code>events.internal.{service}.*</code></td><td><code>events.internal.note.folder.renamed</code></td></tr></tbody></table><p>Every topic published or consumed by a Go service is a constant in that service&#39;s <code>component/eventtopic.go</code>; no inline topic strings.</p><h2 id="payloads" tabindex="-1">Payloads <a class="header-anchor" href="#payloads" aria-label="Permalink to “Payloads”">​</a></h2><p>Cross-service payload types are defined once in <code>api/share/</code> (generated for Go and for <code>@notopia-uit/api-share-gen</code>), never retyped per service. They cover document commits, note created/updated/deleted, workspace deleted, workspace member added/removed, user workspace role updates, user deleted and subscription changes.</p><p>See each service&#39;s page for its own topics, for example <a href="./../services/note/events.html">Note events</a>.</p>`,12)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};